Task: The 'PlayerProfile' class currently handles both player statistics and inventory management. Your task is to refactor it by creating a new class, 'InventoryManager', that exclusively handles the player's inventory, adhering to the Single Responsibility Principle.

Submitted code:
```
class InventoryManager {
    constructor(playerProfileRef) {
        // InventoryManager receives the entire PlayerProfile object
        // even though it only needs the username for logging.
        this.playerProfileRef = playerProfileRef;
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
        console.log(`${this.playerProfileRef.username} picked up a ${item}.`);
    }

    getInventoryList() {
        return `${this.playerProfileRef.username}'s Inventory: ${this.items.join(', ') || 'empty'}`;
    }
}

class PlayerProfile {
    constructor(username) {
        this.username = username;
        this.level = 1;
        this.experience = 0;
        // PlayerProfile instantiates InventoryManager and passes itself
        this.inventoryManager = new InventoryManager(this);
    }

    gainExperience(amount) {
        this.experience += amount;
        if (this.experience >= this.level * 100) {
            this.levelUp();
        }
    }

    levelUp() {
        this.level++;
        this.experience = 0;
        console.log(`${this.username} leveled up to Level ${this.level}!`);
    }

    addItemToInventory(item) {
        this.inventoryManager.addItem(item);
    }

    getInventoryList() {
        return this.inventoryManager.getInventoryList();
    }

    getProfileSummary() {
        return `${this.username} (Level ${this.level}, Exp: ${this.experience})`;
    }
}

// Example Usage
const player1 = new PlayerProfile("HeroicCoder");
player1.gainExperience(50);
player1.addItemToInventory("Healing Potion");
player1.gainExperience(60); // Should level up
player1.addItemToInventory("Magic Sword");

console.log(player1.getProfileSummary());
console.log(player1.getInventoryList());
```

